insert into public.cities (state_id, name, slug, is_active)
select s.id, r.city_name, r.generated_slug, true
from registry r
join public.states s on s.code = r.state_code
on conflict (state_id, name)
do update set
  is_active = true;

do $$
declare
  v_registry_count integer;
  v_state_count integer;
begin
  select count(*)
    into v_registry_count
  from public.cities c
  join public.states s on s.id = c.state_id
  where s.code in (
    'AK',
    'AL',
    'AR',
    'AZ',
    'CA',
    'CO',
    'CT',
    'DC',
    'DE',
    'FL',
    'GA',
    'HI',
    'IA',
    'ID',
    'IL',
    'IN',
    'KS',
    'KY',
    'LA',
    'MA',
    'MD',
    'ME',
    'MI',
    'MN',
    'MO',
    'MS',
    'MT',
    'NC',
    'ND',
    'NE',
    'NH',
    'NJ',
    'NM',
    'NV',
    'NY',
    'OH',
    'OK',
    'OR',
    'PA',
    'PR',
    'RI',
    'SC',
    'SD',
    'TN',
    'TX',
    'UT',
    'VA',
    'VT',
    'WA',
    'WI',
    'WV',
    'WY'
  );

  select count(*)
    into v_state_count
  from public.states
  where code in (
    'AK',
    'AL',
    'AR',
    'AZ',
    'CA',
    'CO',
    'CT',
    'DC',
    'DE',
    'FL',
    'GA',
    'HI',
    'IA',
    'ID',
    'IL',
    'IN',
    'KS',
    'KY',
    'LA',
    'MA',
    'MD',
    'ME',
    'MI',
    'MN',
    'MO',
    'MS',
    'MT',
    'NC',
    'ND',
    'NE',
    'NH',
    'NJ',
    'NM',
    'NV',
    'NY',
    'OH',
    'OK',
    'OR',
    'PA',
    'PR',
    'RI',
    'SC',
    'SD',
    'TN',
    'TX',
    'UT',
    'VA',
    'VT',
    'WA',
    'WI',
    'WV',
    'WY'
  );

  if v_state_count <> 52 then
    raise exception
      'city registry import expected 52 jurisdictions, found %',
      v_state_count;
  end if;

  if v_registry_count < 31108 then
    raise exception
      'city registry import expected at least 31108 cities, found %',
      v_registry_count;
  end if;
end;
$$;

